name: Social Copy Generator

on:
  pull_request:
    types: [opened]

jobs:
  post-comment:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v2

      - name: Set up Node.js
        uses: actions/setup-node@v2
        with:
          node-version: '16'

      - name: Install dependencies
        run: npm install

      - name: Create or update comment
        id: create_comment
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          const { execSync } = require('child_process');
          const { Octokit } = require('@octokit/rest');
          const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });

          const prNumber = parseInt(process.env.GITHUB_REF.split('/').pop());
          const owner = process.env.GITHUB_REPOSITORY.split('/')[0];
          const repo = process.env.GITHUB_REPOSITORY.split('/')[1];

          try {
            const response = await octokit.issues.listComments({
              owner,
              repo,
              issue_number: prNumber,
            });

            let commentId;
            for (const comment of response.data) {
              if (comment.body.includes('Generate social media copies')) {
                commentId = comment.id;
                break;
              }
            }

            if (!commentId) {
              const commentResponse = await octokit.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body: `
                  <details>
                    <summary>Generate social media copies</summary>

                    <p><input type="checkbox" disabled> Generating...</p>

                    <pre><code class="language-markdown"></code></pre>

                    <p><input type="checkbox" disabled> Regenerate</p>
                  </details>
                `,
              });
              commentId = commentResponse.data.id;
            } else {
              await octokit.issues.updateComment({
                owner,
                repo,
                comment_id: commentId,
                body: `
                  <details>
                    <summary>Generate social media copies</summary>

                    <p><input type="checkbox" disabled> Generating...</p>

                    <pre><code class="language-markdown"></code></pre>

                    <p><input type="checkbox" disabled> Regenerate</p>
                  </details>
                `,
              });
            }

            console.log(`Comment ID: ${commentId}`);
          } catch (error) {
            console.error(error);
            throw error;
          }

  regenerate-copy:
    needs: post-comment
    runs-on: ubuntu-latest
    if: github.event_name == 'pull_request' && github.event.action == 'edited' && contains(github.event.pull_request.body, 'Regenerate')
    steps:
      - name: Checkout repository
        uses: actions/checkout@v2

      - name: Set up Node.js
        uses: actions/setup-node@v2
        with:
          node-version: '16'

      - name: Install dependencies
        run: npm install

      - name: Run Claude Code
        id: run_claude
        env:
          CLAUDE_API_KEY: ${{ secrets.CLAUDE_API_KEY }}
        run: |
          const { execSync } = require('child_process');
          const fs = require('fs');
          const path = require('path');

          const prNumber = parseInt(process.env.GITHUB_REF.split('/').pop());
          const owner = process.env.GITHUB_REPOSITORY.split('/')[0];
          const repo = process.env.GITHUB_REPOSITORY.split('/')[1];

          const commentId = process.env.COMMENT_ID;

          try {
            const response = await fetch('https://api.claude.ai/chat', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${process.env.CLAUDE_API_KEY}`,
              },
              body: JSON.stringify({
                message: {
                  text: `
                    Analyze the diff of this PR and generate Twitter/X, LinkedIn, and Blog Post content.

                    PR URL: https://github.com/${owner}/${repo}/pull/${prNumber}
                  `,
                },
              }),
            });

            const data = await response.json();
            const generatedContent = data.message.text;

            await octokit.issues.updateComment({
              owner,
              repo,
              comment_id: commentId,
              body: `
                <details>
                  <summary>Generate social media copies</summary>

                  <p><input type="checkbox" disabled> Generated</p>

                  <pre><code class="language-markdown">${generatedContent}</code></pre>

                  <p><input type="checkbox"> Regenerate</p>
                </details>
              `,
            });
          } catch (error) {
            console.error(error);
            throw error;
          }
